<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake</title>
<style>
  :root {
    --bg: #0d1117;
    --panel: #161b22;
    --accent: #39d353;
    --accent-dim: #26a641;
    --food: #f85149;
    --text: #e6edf3;
    --muted: #8b949e;
    --border: #30363d;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    height: 100%;
    background: var(--bg);
    color: var(--text);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  }
  body {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    gap: 18px;
    padding: 24px;
  }
  h1 {
    margin: 0;
    font-size: 22px;
    letter-spacing: 2px;
    font-weight: 600;
    color: var(--text);
  }
  h1 span { color: var(--accent); }
  .hud {
    display: flex;
    align-items: center;
    gap: 24px;
    width: 100%;
    max-width: 460px;
    justify-content: space-between;
  }
  #score {
    font-size: 20px;
    font-variant-numeric: tabular-nums;
    font-weight: 700;
  }
  #score b { color: var(--accent); }
  #status {
    font-size: 13px;
    color: var(--muted);
    letter-spacing: 1px;
    text-transform: uppercase;
  }
  #status.dead { color: var(--food); }
  .board-wrap {
    position: relative;
    padding: 10px;
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 12px;
    box-shadow: 0 12px 40px rgba(0,0,0,0.5);
  }
  #snake {
    display: block;
    width: 460px;
    height: 460px;
    max-width: 80vw;
    max-height: 80vw;
    border-radius: 6px;
    background: #0a0e13;
    image-rendering: pixelated;
    touch-action: none;
  }
  .overlay {
    position: absolute;
    inset: 10px;
    display: none;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    gap: 8px;
    background: rgba(6,9,13,0.78);
    border-radius: 6px;
    text-align: center;
  }
  .overlay.show { display: flex; }
  .overlay .big { font-size: 26px; font-weight: 700; color: var(--food); }
  .overlay .sub { font-size: 13px; color: var(--muted); }
  .controls {
    display: flex;
    gap: 10px;
  }
  button {
    appearance: none;
    border: 1px solid var(--border);
    background: #21262d;
    color: var(--text);
    font-size: 14px;
    font-weight: 600;
    padding: 9px 20px;
    border-radius: 8px;
    cursor: pointer;
    transition: background .15s, border-color .15s, transform .05s;
  }
  button:hover { background: #2d333b; border-color: #484f58; }
  button:active { transform: translateY(1px); }
  #start { border-color: var(--accent-dim); }
  #start:hover { background: rgba(57,211,83,0.15); }
  .hint {
    font-size: 12px;
    color: var(--muted);
    letter-spacing: .5px;
  }
</style>
</head>
<body>
  <h1>SNA<span>KE</span></h1>

  <div class="hud">
    <div id="score">Score: <b>0</b></div>
    <div id="status">Ready</div>
  </div>

  <div class="board-wrap">
    <canvas id="snake" width="460" height="460"></canvas>
    <div class="overlay" id="overlay">
      <div class="big">Game Over</div>
      <div class="sub">Press Reset or Start to play again</div>
    </div>
  </div>

  <div class="controls">
    <button id="start">Start</button>
    <button id="pause">Pause</button>
    <button id="reset">Reset</button>
  </div>

  <div class="hint">Use the arrow keys to steer • eat the red food to grow</div>

<script>
(function () {
  "use strict";

  const COLS = 20;
  const ROWS = 20;

  const canvas = document.getElementById("snake");
  const ctx = canvas.getContext("2d");
  const scoreEl = document.querySelector("#score b");
  const statusEl = document.getElementById("status");
  const overlayEl = document.getElementById("overlay");
  const startBtn = document.getElementById("start");
  const pauseBtn = document.getElementById("pause");
  const resetBtn = document.getElementById("reset");

  const CELL = canvas.width / COLS; // canvas is square, COLS==ROWS

  // ---- game state ----
  let snakeCells;   // array of [x,y], head first
  let foodCell;     // [x,y]
  let dir;          // current heading {x,y}
  let queuedDir;    // next heading applied on tick
  let isAlive;
  let scoreVal;
  let timer = null;
  const TICK_MS = 110;

  const DIRS = {
    up:    { x: 0,  y: -1 },
    down:  { x: 0,  y: 1  },
    left:  { x: -1, y: 0  },
    right: { x: 1,  y: 0  },
  };

  function cellsEqual(a, b) { return a[0] === b[0] && a[1] === b[1]; }

  function occupied(x, y) {
    for (let i = 0; i < snakeCells.length; i++) {
      if (snakeCells[i][0] === x && snakeCells[i][1] === y) return true;
    }
    return false;
  }

  function placeFoodRandom() {
    const free = [];
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        if (!occupied(x, y)) free.push([x, y]);
      }
    }
    if (free.length === 0) { foodCell = null; return; }
    // deterministic-ish random pick
    const idx = Math.floor(Math.random() * free.length);
    foodCell = free[idx];
  }

  function reset() {
    const cy = Math.floor(ROWS / 2);
    const sx = Math.floor(COLS / 2);
    // length 3, head first, heading right
    snakeCells = [
      [sx, cy],
      [sx - 1, cy],
      [sx - 2, cy],
    ];
    dir = { x: 1, y: 0 };
    queuedDir = { x: 1, y: 0 };
    isAlive = true;
    scoreVal = 0;
    placeFoodRandom();
    render();
    updateHud();
  }

  function tick() {
    if (!isAlive) return;

    // apply queued direction (already vetted against 180° reversal)
    dir = queuedDir;

    const head = snakeCells[0];
    const nx = head[0] + dir.x;
    const ny = head[1] + dir.y;

    // wall collision
    if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS) {
      die();
      return;
    }

    const ate = foodCell && nx === foodCell[0] && ny === foodCell[1];

    // self collision: check against body. The tail moves away unless we eat,
    // so the tail cell is walkable when not eating.
    const bodyLimit = ate ? snakeCells.length : snakeCells.length - 1;
    for (let i = 0; i < bodyLimit; i++) {
      if (snakeCells[i][0] === nx && snakeCells[i][1] === ny) {
        die();
        return;
      }
    }

    snakeCells.unshift([nx, ny]);
    if (ate) {
      scoreVal += 1;
      placeFoodRandom();
    } else {
      snakeCells.pop();
    }

    render();
    updateHud();
  }

  function die() {
    isAlive = false;
    stopLoop();
    statusEl.textContent = "Game Over";
    statusEl.classList.add("dead");
    overlayEl.classList.add("show");
    render();
  }

  function setDir(name) {
    const nd = DIRS[name];
    if (!nd) return;
    // ignore 180° reversal relative to current heading
    if (nd.x === -dir.x && nd.y === -dir.y) return;
    queuedDir = nd;
  }

  function setFood(x, y) {
    x = Math.max(0, Math.min(COLS - 1, Math.floor(x)));
    y = Math.max(0, Math.min(ROWS - 1, Math.floor(y)));
    foodCell = [x, y];
    render();
  }

  // ---- rendering ----
  function drawGrid() {
    ctx.fillStyle = "#0a0e13";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = "rgba(255,255,255,0.03)";
    ctx.lineWidth = 1;
    for (let i = 1; i < COLS; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL, 0);
      ctx.lineTo(i * CELL, canvas.height);
      ctx.stroke();
    }
    for (let j = 1; j < ROWS; j++) {
      ctx.beginPath();
      ctx.moveTo(0, j * CELL);
      ctx.lineTo(canvas.width, j * CELL);
      ctx.stroke();
    }
  }

  function roundedCell(x, y, pad, r, color) {
    const px = x * CELL + pad;
    const py = y * CELL + pad;
    const s = CELL - pad * 2;
    ctx.fillStyle = color;
    ctx.beginPath();
    if (ctx.roundRect) {
      ctx.roundRect(px, py, s, s, r);
    } else {
      ctx.rect(px, py, s, s);
    }
    ctx.fill();
  }

  function render() {
    drawGrid();

    // food
    if (foodCell) {
      const fx = foodCell[0] * CELL + CELL / 2;
      const fy = foodCell[1] * CELL + CELL / 2;
      ctx.fillStyle = "#f85149";
      ctx.beginPath();
      ctx.arc(fx, fy, CELL * 0.32, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = "rgba(255,255,255,0.35)";
      ctx.beginPath();
      ctx.arc(fx - CELL * 0.1, fy - CELL * 0.1, CELL * 0.09, 0, Math.PI * 2);
      ctx.fill();
    }

    // snake body
    for (let i = snakeCells.length - 1; i >= 0; i--) {
      const c = snakeCells[i];
      const isHead = i === 0;
      const t = snakeCells.length > 1 ? i / (snakeCells.length - 1) : 0;
      // gradient from bright head to dimmer tail
      const color = isHead
        ? "#39d353"
        : `rgb(${Math.round(38 + (57 - 38) * (1 - t))}, ${Math.round(120 + (166 - 120) * (1 - t))}, ${Math.round(60 + (83 - 60) * (1 - t))})`;
      roundedCell(c[0], c[1], isHead ? 1 : 2, isHead ? 5 : 4, color);
    }

    // eyes on head
    if (snakeCells.length) {
      const h = snakeCells[0];
      const cx = h[0] * CELL;
      const cy = h[1] * CELL;
      ctx.fillStyle = "#0a0e13";
      const eo = CELL * 0.26; // eye offset
      const er = CELL * 0.08; // eye radius
      let e1x, e1y, e2x, e2y;
      if (dir.x === 1) { e1x = cx + CELL - eo; e1y = cy + eo; e2x = cx + CELL - eo; e2y = cy + CELL - eo; }
      else if (dir.x === -1) { e1x = cx + eo; e1y = cy + eo; e2x = cx + eo; e2y = cy + CELL - eo; }
      else if (dir.y === -1) { e1x = cx + eo; e1y = cy + eo; e2x = cx + CELL - eo; e2y = cy + eo; }
      else { e1x = cx + eo; e1y = cy + CELL - eo; e2x = cx + CELL - eo; e2y = cy + CELL - eo; }
      ctx.beginPath(); ctx.arc(e1x, e1y, er, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(e2x, e2y, er, 0, Math.PI * 2); ctx.fill();
    }
  }

  function updateHud() {
    scoreEl.textContent = scoreVal;
    if (isAlive) {
      statusEl.classList.remove("dead");
      statusEl.textContent = timer ? "Playing" : "Paused";
      overlayEl.classList.remove("show");
    }
  }

  // ---- loop control ----
  function startLoop() {
    if (!isAlive) reset();
    if (timer) return;
    timer = setInterval(tick, TICK_MS);
    updateHud();
  }
  function stopLoop() {
    if (timer) { clearInterval(timer); timer = null; }
  }
  function pauseLoop() {
    if (timer) { stopLoop(); updateHud(); }
  }

  // ---- input ----
  window.addEventListener("keydown", function (e) {
    let handled = true;
    switch (e.key) {
      case "ArrowUp":    setDir("up");    break;
      case "ArrowDown":  setDir("down");  break;
      case "ArrowLeft":  setDir("left");  break;
      case "ArrowRight": setDir("right"); break;
      case " ":          if (timer) pauseLoop(); else startLoop(); break;
      default: handled = false;
    }
    if (handled) e.preventDefault();
  });

  startBtn.addEventListener("click", startLoop);
  pauseBtn.addEventListener("click", pauseLoop);
  resetBtn.addEventListener("click", function () {
    stopLoop();
    reset();
  });

  // ---- programmatic API for grading ----
  window.game = {
    w: COLS,
    h: ROWS,
    reset: reset,
    tick: tick,
    setDir: setDir,
    setFood: setFood,
    snake: function () { return snakeCells.map(function (c) { return [c[0], c[1]]; }); },
    food: function () { return foodCell ? [foodCell[0], foodCell[1]] : null; },
    alive: function () { return isAlive; },
    score: function () { return scoreVal; },
  };

  // boot
  reset();
})();
</script>
</body>
</html>
